import { beforeEach, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({ limit: vi.fn() }));
vi.mock("@/lib/rate-limit", async (importOriginal) => ({
  ...(await importOriginal()),
  checkDocsSearchRateLimit: mocks.limit,
}));
// The source is generated by the MDX compiler, which is not part of this test runner.
vi.mock("@/lib/search/corpus", () => ({
  searchablePages: () => [
    {
      url: "/docs/cloud",
      data: {
        title: "Assistant Cloud",
        description: "Persist chats",
        structuredData: () => ({
          contents: [
            { content: "Threads sync across devices." },
            { content: "Your functions can read the thread." },
          ],
        }),
      },
    },
    {
      url: "/docs/tools",
      data: {
        title: "Tools",
        description: "Let the model call functions",
        structuredData: () => ({
          contents: [
            { content: "Pause a call for human-in-the-loop approval." },
          ],
        }),
      },
    },
  ],
}));
import { GET } from "./route";

beforeEach(() => {
  vi.stubEnv("JEV_KEY", "test-key");
  mocks.limit.mockResolvedValue(null);
});
afterEach(() => {
  vi.unstubAllGlobals();
  vi.unstubAllEnvs();
});
const request = (query: string, scope = "All") =>
  new Request(
    `https://www.assistant-ui.com/api/search/suggest?${new URLSearchParams({ query, scope })}`,
  );

it("validates query length and the scope before doing paid work", async () => {
  const fetcher = vi.fn();
  vi.stubGlobal("fetch", fetcher);
  expect((await GET(request("ab"))).status).toBe(400);
  expect((await GET(request("x".repeat(121)))).status).toBe(400);
  expect((await GET(request("save history", "Unknown"))).status).toBe(400);
  expect(fetcher).not.toHaveBeenCalled();
  expect(mocks.limit).not.toHaveBeenCalled();
});

it("serves body-text matches without a key", async () => {
  vi.stubEnv("JEV_KEY", "");
  const fetcher = vi.fn();
  vi.stubGlobal("fetch", fetcher);
  const response = await GET(request("human in the loop"));
  expect(await response.json()).toEqual({
    enabled: true,
    pages: [
      {
        url: "/docs/tools",
        title: "Tools",
        description: "Let the model call functions",
      },
    ],
  });
  expect(response.headers.get("cache-control")).toBe("no-store");
  expect(response.headers.get("x-robots-tag")).toBe("noindex");
  expect(fetcher).not.toHaveBeenCalled();
  expect(mocks.limit).toHaveBeenCalledTimes(1);
});

it("matches body text only when every word is on the page", async () => {
  vi.stubEnv("JEV_KEY", "");
  const response = await GET(request("human sync"));
  expect(await response.json()).toEqual({ enabled: true, pages: [] });
});

it("leaves out pages the browser index already lists for the query", async () => {
  vi.stubEnv("JEV_KEY", "");
  // The Tools description says "functions", so the palette already lists it.
  const response = await GET(request("functions"));
  expect(await response.json()).toEqual({
    enabled: true,
    pages: [
      {
        url: "/docs/cloud",
        title: "Assistant Cloud",
        description: "Persist chats",
      },
    ],
  });
});

it("respects the scope for body-text matches", async () => {
  vi.stubEnv("JEV_KEY", "");
  const response = await GET(request("human in the loop", "Elements"));
  expect(await response.json()).toEqual({ enabled: true, pages: [] });
});

it("enforces rate limits before making a Jev request", async () => {
  const fetcher = vi.fn();
  vi.stubGlobal("fetch", fetcher);
  mocks.limit.mockResolvedValue(new Response("Limited", { status: 429 }));
  expect((await GET(request("human in the loop"))).status).toBe(429);
  expect(fetcher).not.toHaveBeenCalled();
});

it("serves body-text matches without Jev when the limiter is unavailable", async () => {
  const fetcher = vi.fn();
  vi.stubGlobal("fetch", fetcher);
  mocks.limit.mockResolvedValue(new Response("Unavailable", { status: 503 }));
  const response = await GET(request("human in the loop"));
  expect(response.status).toBe(200);
  expect(await response.json()).toEqual({
    enabled: true,
    pages: [
      {
        url: "/docs/tools",
        title: "Tools",
        description: "Let the model call functions",
      },
    ],
  });
  expect(fetcher).not.toHaveBeenCalled();
});

it("returns catalogue data rather than a URL invented by the model", async () => {
  vi.stubGlobal(
    "fetch",
    vi.fn().mockResolvedValue(
      Response.json({
        answers: {
          pages_0: {
            type: "choice",
            choice: "page_0",
            confidence: 1,
            probabilities: { page_0: 1 },
          },
        },
      }),
    ),
  );
  const response = await GET(request("save history"));
  expect(response.status).toBe(200);
  expect(await response.json()).toEqual({
    enabled: true,
    pages: [
      {
        url: "/docs/cloud",
        title: "Assistant Cloud",
        description: "Persist chats",
      },
    ],
  });
});

it("lists the model's picks first, then body-text matches it did not pick", async () => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async () =>
      Response.json({
        answers: {
          pages_0: {
            type: "choice",
            choice: "page_0",
            confidence: 1,
            probabilities: { page_0: 1 },
          },
        },
      }),
    ),
  );
  // The route keeps its Jev client, and the client keeps the fetch it was made with.
  vi.resetModules();
  const { GET: fresh } = await import("./route");

  const pages = (await (await fresh(request("human loop"))).json()).pages;
  expect(pages.map((page: { url: string }) => page.url)).toEqual([
    "/docs/cloud",
    "/docs/tools",
  ]);
});

it("retries a misspelled query with the closest words in the docs", async () => {
  vi.stubEnv("JEV_KEY", "");
  const pages = (await (await GET(request("aproval"))).json()).pages;
  expect(pages.map((page: { url: string }) => page.url)).toEqual([
    "/docs/tools",
  ]);
});

it("keeps Jev's picks when the content index fails", async () => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async () =>
      Response.json({
        answers: {
          pages_0: {
            type: "choice",
            choice: "page_0",
            confidence: 1,
            probabilities: { page_0: 1 },
          },
        },
      }),
    ),
  );
  vi.resetModules();
  vi.doMock("@/lib/search/content-index", () => ({
    buildContentIndex: async () => {
      throw new Error("index unavailable");
    },
  }));
  const logged = vi.spyOn(console, "error").mockImplementation(() => {});
  try {
    const { GET: fresh } = await import("./route");
    const response = await fresh(request("save history"));
    expect(response.status).toBe(200);
    const pages = (await response.json()).pages;
    expect(pages.map((page: { url: string }) => page.url)).toEqual([
      "/docs/cloud",
    ]);
  } finally {
    logged.mockRestore();
    vi.doUnmock("@/lib/search/content-index");
  }
});
